import logging
import json
from typing import Any, Callable, Awaitable
from fastmcp import Server

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(name)s - %(levelname)s - %(message)s"
)
logger = logging.getLogger("request_logger")


class RequestLoggingMiddleware:
    """Custom middleware that logs all incoming requests."""

    def __init__(self, app: Callable[[dict[str, Any]], Awaitable[Any]]):
        self.app = app

    async def __call__(self, message: dict[str, Any]) -> Any:
        logger.info(f"Incoming request: {json.dumps(message, default=str)}")
        result = await self.app(message)
        logger.info(f"Request processed, response type: {type(result).__name__}")
        return result


# Create server instance
server = Server("logging-example-server")

# Attach middleware to the server
server.middleware(RequestLoggingMiddleware)


@server.list_resources()
async def list_resources():
    """List available resources."""
    return [
        {
            "uri": "memory://sample",
            "name": "Sample Resource",
            "description": "A sample resource for demonstration",
            "mimeType": "text/plain",
        }
    ]


@server.list_tools()
async def list_tools():
    """List available tools."""
    return [
        {
            "name": "echo",
            "description": "Echo tool that returns the input message",
            "inputSchema": {
                "type": "object",
                "properties": {
                    "message": {"type": "string", "description": "Message to echo"}
                },
                "required": ["message"],
            },
        }
    ]


@server.call_tool()
async def call_tool(name: str, arguments: dict[str, Any]):
    """Handle tool calls."""
    if name == "echo":
        message = arguments.get("message", "")
        return [{"type": "text", "text": f"Echo: {message}"}]
    raise ValueError(f"Unknown tool: {name}")


if __name__ == "__main__":
    server.run(stdio=True)

